         break;
      case 2:
         rtxPrintToStream (pctxt, " = pre-emptiveRelease\n");
         break;
      case 3:
         rtxPrintToStream (pctxt, " = congestion\n");
         break;
      case 4:
         rtxPrintToStream (pctxt, " = re-establishmentReject\n");
