int asn1PrtToStrm_rrc_CN_DomainInformationListFull (OSCTXT *pctxt, 
   const char* name, const rrc_CN_DomainInformationListFull* pvalue)
{
   char namebuf[512], numbuf[32];
   OSUINT32 xx1;

   for (xx1 = 0; xx1 < pvalue->n; xx1++) {
      rtxUIntToCharStr (xx1, numbuf, sizeof(numbuf), 0);
      rtxStrJoin (namebuf, sizeof(namebuf), name, "[", numbuf, "]", 0);
      asn1PrtToStrm_rrc_CN_DomainInformationFull (pctxt, namebuf, &pvalue->elem[xx1]);
   }
   return 0;
}

